INSERT INTO questions (id, content, difficulty, sub_category_id) VALUES
('b0000000-0000-0000-0018-000000000001', 'OSI 7계층은 무엇이며, 각각의 계층에서 하는 역할은 무엇인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000018'),
('b0000000-0000-0000-0018-000000000002', 'TCP/IP 4계층 모델에 대해 설명해 보세요.', 'EASY', 'b0000000-0000-0000-0000-000000000018'),
('b0000000-0000-0000-0018-000000000003', 'LAN과 WAN의 차이는 무엇인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000018'),
('b0000000-0000-0000-0018-000000000004', 'HTTP와 HTTPS의 차이는 무엇인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000018'),
('b0000000-0000-0000-0018-000000000005', 'TCP와 UDP의 차이를 설명해 주세요.', 'EASY', 'b0000000-0000-0000-0000-000000000018'),
('b0000000-0000-0000-0018-000000000006', '3-way handshake와 4-way handshake 과정은 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000018'),
('b0000000-0000-0000-0018-000000000007', 'OSI 모델의 각 계층에서 사용하는 프로토콜이나 기술의 예를 들어보세요.', 'MEDIUM', 'b0000000-0000-0000-0000-000000000018'),
('b0000000-0000-0000-0018-000000000008', 'IP 주소는 무엇이고 IPv4와 IPv6의 차이는 무엇인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000018'),
('b0000000-0000-0000-0018-000000000009', '공인 IP와 사설 IP의 차이는 무엇인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000018'),
('b0000000-0000-0000-0018-000000000010', 'SMTP는 어떤 계층의 어떤 목적으로 쓰이는 프로토콜인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000018'),
('b0000000-0000-0000-0018-000000000011', 'FTP와 SFTP의 차이점을 설명해 보세요.', 'MEDIUM', 'b0000000-0000-0000-0000-000000000018'),
('b0000000-0000-0000-0018-000000000012', 'ARP(Address Resolution Protocol)는 어떤 역할을 하나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000018'),
('b0000000-0000-0000-0018-000000000013', 'DNS Lookup 과정을 간단히 설명해 주세요.', 'MEDIUM', 'b0000000-0000-0000-0000-000000000018'),
('b0000000-0000-0000-0018-000000000014', '네트워크에서 멱등성(Idempotence)이란 개념은 무엇인가요?', 'HARD', 'b0000000-0000-0000-0000-000000000018'),
('b0000000-0000-0000-0018-000000000015', '로드 밸런서(Load Balancer)는 무엇이며 어떻게 동작하나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000018'),
('b0000000-0000-0000-0018-000000000016', '대칭 키 암호화와 비대칭 키 암호화의 차이는 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000018'),
('b0000000-0000-0000-0018-000000000017', 'SSL/TLS의 기본 개념과 핸드셰이크 과정을 설명해 주세요.', 'HARD', 'b0000000-0000-0000-0000-000000000018'),
('b0000000-0000-0000-0018-000000000018', 'Wi-Fi와 이더넷(Ethernet)의 장단점을 비교해 보세요.', 'MEDIUM', 'b0000000-0000-0000-0000-000000000018'),
('b0000000-0000-0000-0018-000000000019', 'ICMP 프로토콜은 무엇이며 언제 사용되나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000018'),
('b0000000-0000-0000-0018-000000000020', 'QoS(Quality of Service)란 무엇이며, 네트워크에서 어떻게 구현되나요?', 'HARD', 'b0000000-0000-0000-0000-000000000018'),
('b0000000-0000-0000-0018-000000000021', '멀티캐스트(Multicast)와 유니캐스트(Unicast), 브로드캐스트(Broadcast)의 차이는?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000018'),
('b0000000-0000-0000-0018-000000000022', 'VPN(Virtual Private Network)은 무엇이고 어떤 경우에 사용되나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000018'),
('b0000000-0000-0000-0018-000000000023', '시퀀스 번호(Sequence Number)와 확인 응답 번호(ACK Number)가 TCP에서 하는 역할은?', 'HARD', 'b0000000-0000-0000-0000-000000000018'),
('b0000000-0000-0000-0018-000000000024', '혼잡 제어 알고리즘 중 TCP Tahoe와 Reno의 차이는?', 'HARD', 'b0000000-0000-0000-0000-000000000018'),
('b0000000-0000-0000-0018-000000000025', 'SSH 프로토콜은 무엇이며 주로 어떤 목적으로 사용되나요?', 'EASY', 'b0000000-0000-0000-0000-000000000018'),
('b0000000-0000-0000-0018-000000000026', '네트워크 지연(Latency)을 줄이기 위한 방법에는 무엇이 있을까요?', 'HARD', 'b0000000-0000-0000-0000-000000000018');
